def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != 0:
                                seen[nr][nc] = True
                                stack.append((nr, nc))
                components.append(comp)
    for comp in components:
        minr = min(r for r, _ in comp)
        maxr = max(r for r, _ in comp)
        maxc = max(c for _, c in comp)
        r0, r1 = max(0, minr - 1), min(h - 1, maxr + 1)
        c0, c1 = 0, min(w - 1, maxc + 1)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
