def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0

    # Collect solid blocks by color (non-zero, non-4 colors) with their bounds
    blocks = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                if v not in blocks:
                    blocks[v] = [r, r, c, c]
                else:
                    b = blocks[v]
                    b[0] = min(b[0], r); b[1] = max(b[1], r)
                    b[2] = min(b[2], c); b[3] = max(b[3], c)

